import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";var i=JSON.parse(`{"title":"Automated Cron Jobs in BRAIN CoGS (Developer Guide)","description":"","frontmatter":{"title":"Automated Cron Jobs in BRAIN CoGS (Developer Guide)","lang":"en-US"},"headers":[],"relativePath":"software/automated_cronjobs.md","filePath":"software/automated_cronjobs.md"}`),a={name:`software/automated_cronjobs.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="automated-cronjobs-in-braincogs-developer-guide" tabindex="-1">Automated Cron Jobs in BRAIN CoGS (Developer Guide) <a class="header-anchor" href="#automated-cronjobs-in-braincogs-developer-guide" aria-label="Permalink to “Automated Cron Jobs in BRAIN CoGS (Developer Guide)”">​</a></h1><ul><li>Some processes in BRAIN CoGS run automatically.</li><li>All of them run on the <strong>u19proc2</strong> (g-bcogs-u19proc2.pni.princeton.edu) virtual machine, administered by PNI Help. Contact Garrett T. McGrath (gmcgrath@princeton.edu) for permissions.</li><li>All processes run under the <strong>u19prod</strong> user account, so they are not linked to any personal account.</li></ul><h2 id="list-of-automated-processes-in-braincogs" tabindex="-1">List of automated processes in BRAIN CoGS <a class="header-anchor" href="#list-of-automated-processes-in-braincogs" aria-label="Permalink to “List of automated processes in BRAIN CoGS”">​</a></h2><ul><li><a href="#alert-system-daily-routine">Alert system daily routine</a></li><li><a href="#behavior-manipulation-optogenetics-pupillometry-tables-ingestion-matlab-cronjob">Behavior, manipulation, optogenetics and pupillometry table ingestion</a></li><li><a href="#tech-alert">Tech alert</a></li><li><a href="#rig-maintenance">Rig maintenance</a></li><li><a href="#missing-sync-behavior">Missing sync behavior</a></li><li><a href="#water-weight-alert">Water-weight alert</a></li><li><a href="#live-stats-monitor-routine">Live stats monitor routine</a></li><li><a href="#ephys-imaging-automation-pipeline-process">Ephys/imaging automation pipeline process</a></li><li><a href="#pupillometry-pipeline-queue-process">Pupillometry pipeline queue process</a></li><li><a href="#pupillometry-pipeline-check-process">Pupillometry pipeline check process</a></li></ul><h2 id="alert-system-daily-routine" tabindex="-1">Alert system daily routine <a class="header-anchor" href="#alert-system-daily-routine" aria-label="Permalink to “Alert system daily routine”">​</a></h2><ul><li><strong>Execution schedule:</strong> daily at 3:00 am</li><li><strong>Location in u19proc2:</strong> /home/u19prod/Datajoint_projs/U19-pipeline_python/u19_pipeline/alert_system/call_cronjob_alert.sh</li><li><strong>Overview:</strong> Calls the <a href="https://github.com/BrainCOGS/U19-pipeline-python/blob/master/u19_pipeline/alert_system/cronjob_alert.py">cronjob_alert.py script</a>, which: <ul><li>Executes <strong>main_old_log_deletion()</strong>: deletes logs older than 2 weeks from every cron job&#39;s main log directory.</li><li>Executes <strong>main_live_session_stats_deletion()</strong>: moves records older than 2 weeks from acquisition.LiveSessionStats to acquisition.HistoricSessionStats, to keep the former table small for the live stats monitor routine.</li><li>Executes <strong>main_noDB_backup</strong>: copies auxiliary files for offline ViRMEn mode (<a href="/software/virmen_developer.html#virmen-offline">more info</a>).</li><li>(Deprecated) Runs the custom alerts for users (see the <a href="/software/alert_system.html">alert system section</a>).</li></ul></li><li><strong>Log files:</strong> /home/u19prod/log/cronlog_alert/night_cron_log_(datetime execution)</li></ul><h2 id="behavior-manipulation-optogenetics-pupillometry-tables-ingestion-matlab-cronjob" tabindex="-1">Behavior, Manipulation, Optogenetics, Pupillometry tables ingestion (MATLAB Cronjob) <a class="header-anchor" href="#behavior-manipulation-optogenetics-pupillometry-tables-ingestion-matlab-cronjob" aria-label="Permalink to “Behavior, Manipulation, Optogenetics, Pupillometry tables ingestion (MATLAB Cronjob)”">​</a></h2><ul><li><strong>Execution schedule:</strong> daily at 4:00 am</li><li><strong>Location in u19proc2:</strong> /home/u19prod/Datajoint_projs/U19-pipeline-matlab/scripts/call_u19_night_cronjob.sh</li><li><strong>Overview:</strong> Calls the <a href="https://github.com/BrainCOGS/U19-pipeline-matlab/blob/master/scripts/populate_tables.m">populate_tables.m script</a>. Ingests all behavior-related tables from acquisition.SessionStarted and acquisition.Session for records created that day, and ingests the schedule for the next day. See the populate_tables.m script for details.</li><li><strong>Log files:</strong> /home/u19prod/log/night_cronjob_log/night_cron_log2_(datetime execution)</li></ul><h2 id="tech-alert" tabindex="-1">Tech Alert <a class="header-anchor" href="#tech-alert" aria-label="Permalink to “Tech Alert”">​</a></h2><ul><li><strong>Execution schedule:</strong> daily at 7:00 am</li><li><strong>Location in u19proc2:</strong> /home/u19prod/Datajoint_projs/U19-pipeline_python/u19_pipeline/alert_system/tech_alert/call_cronjob_tech_alert.sh</li><li><strong>Overview:</strong> Calls the <a href="https://github.com/BrainCOGS/U19-pipeline-python/blob/master/u19_pipeline/alert_system/tech_alert/tech_alert.py">tech_alert.py script</a>.</li><li><strong>Log files:</strong> /home/u19prod/log/tech_alert/ta_log_(datetime execution)</li><li>Executes <strong>tech_alert.py()</strong></li><li>Executes <strong>cronjob_locked_tables_alert()</strong>: checks for locked tables at startup (in theory, locked tables mean the DB is not writable). Sends a dev-notifications alert.</li><li>Executes <strong>cronjob_schedule_check()</strong>: checks whether any subjects are scheduled for training the next day. If none are, the schedule population script most likely failed. Sends a dev-notifications alert.</li></ul><h2 id="rig-maintenance" tabindex="-1">Rig Maintenance <a class="header-anchor" href="#rig-maintenance" aria-label="Permalink to “Rig Maintenance”">​</a></h2><ul><li><strong>Execution schedule:</strong> daily at 7:00 am</li><li><strong>Location in u19proc2:</strong> /home/u19prod/Datajoint_projs/U19-pipeline_python/u19_pipeline/alert_system/rig_maintenance/call_cronjob_check_rig_maintenance.sh</li><li><strong>Overview:</strong> Calls the <a href="https://github.com/BrainCOGS/U19-pipeline-python/blob/master/u19_pipeline/alert_system/rig_maintenance/check_rig_maintenance.py#L532">check_rig_maintenance.py script</a>.</li><li><strong>Log files:</strong> /home/u19prod/log/rig_maintenance_alert/rma_log_$(datetime execution)</li></ul><h2 id="missing-sync-behavior" tabindex="-1">Missing Sync Behavior <a class="header-anchor" href="#missing-sync-behavior" aria-label="Permalink to “Missing Sync Behavior”">​</a></h2><ul><li><strong>Execution schedule:</strong> daily at 7:00 am</li><li><strong>Location in u19proc2:</strong> /home/u19prod/Datajoint_projs/U19-pipeline_python/u19_pipeline/alert_system/automatic_job/call_populate_missing_syncbehavior.sh</li><li><strong>Overview:</strong> Calls the <a href="https://github.com/BrainCOGS/U19-pipeline-python/blob/master/u19_pipeline/automatic_job/populate_missing_syncbehavior_ephys.py">populate_missing_syncbehavior_ephys.py script</a>. Populates the <strong>ephys_pipeline.BehaviorSync</strong> table. Since BehaviorSync requires the session&#39;s behavior data to already be in the DB (ingested <a href="/software/automated_cronjobs.html#behavior-manipulation-optogenetics-pupillometry-tables-ingestion-matlab-cronjob">here</a> at 4 a.m.), this table is populated here rather than in the ephys pipeline.</li><li><strong>Log files:</strong> /home/u19prod/log/missing_syncbehavior_logs/msbhl_$(datetime execution)</li></ul><h2 id="water-weight-alert" tabindex="-1">Water-Weight Alert <a class="header-anchor" href="#water-weight-alert" aria-label="Permalink to “Water-Weight Alert”">​</a></h2><ul><li><strong>Execution schedule:</strong> daily at 6:00 &amp; 7:00 pm</li><li><strong>Location in u19proc2:</strong> /home/u19prod/Datajoint_projs/U19-pipeline_python/u19_pipeline/alert_system/water_weigh_alert/call_cronjob_water_weigh_alert.sh</li><li><strong>Overview:</strong> Calls the <a href="https://github.com/BrainCOGS/U19-pipeline-python/blob/master/u19_pipeline/alert_system/water_weigh_alert/water_weigh_alert.py#L664">water_weigh_alert.py script</a>. Checks whether subjects were watered, weighed, trained, and transported according to the current schedule. Alerts for missing actions are sent to the subject-health channel.</li><li><strong>Log files:</strong> /home/u19prod/log/water_weigh_alert/wwa_log_$(datetime execution)</li></ul><h2 id="live-stats-monitor-routine" tabindex="-1">Live Stats Monitor routine <a class="header-anchor" href="#live-stats-monitor-routine" aria-label="Permalink to “Live Stats Monitor routine”">​</a></h2><ul><li><strong>Execution schedule:</strong> every 5 minutes</li><li><strong>Location in u19proc2:</strong> /home/u19prod/Datajoint_projs/U19-pipeline_python/u19_pipeline/alert_system/live_monitor_alert/call_cronjob_live_monitor_alert.sh</li><li><strong>Overview:</strong> Calls the <a href="https://github.com/BrainCOGS/U19-pipeline-python/blob/master/u19_pipeline/alert_system/live_monitor_alert/live_monitor_alert.py#L67">main live monitor function</a>. Checks whether any subject has gone a &quot;long&quot; time (&gt; 20 min) without a valid, successful trial during training, and if so, raises an alarm.</li><li><strong>Log files:</strong> /home/u19prod/log/live_stats_monitor/lsmlog2_(datetime execution)</li></ul><h2 id="ephys-imaging-automation-pipeline-process" tabindex="-1">Ephys/Imaging Automation Pipeline process <a class="header-anchor" href="#ephys-imaging-automation-pipeline-process" aria-label="Permalink to “Ephys/Imaging Automation Pipeline process”">​</a></h2><ul><li><strong>Execution schedule:</strong> every 30 minutes</li><li><strong>Location in u19proc2:</strong> /home/u19prod/Datajoint_projs/U19-pipeline_python/u19_pipeline/automatic_job/call_cronjob_automatic_job.sh</li><li><strong>Overview:</strong> Calls <a href="https://github.com/BrainCOGS/U19-pipeline-python/blob/master/u19_pipeline/automatic_job/cronjob_automatic_job.py">cronjob_automatic_job.py (the ephys/imaging cron job script)</a>. Checks whether a new recording has been added from the <a href="https://github.com/BrainCOGS/RecordingProcessJobGUI">RecordingProcessJobGUI</a> or whether a job (recording process) has advanced to a new status. If so, the &quot;next&quot; function or process is called for the recording and/or job.</li><li><strong>Log files:</strong> /home/u19prod/log/automation_pipeline_log/aplog_(datetime execution)</li></ul><h2 id="pupillometry-pipeline-queue-process" tabindex="-1">Pupillometry Pipeline Queue process <a class="header-anchor" href="#pupillometry-pipeline-queue-process" aria-label="Permalink to “Pupillometry Pipeline Queue process”">​</a></h2><ul><li><strong>Execution schedule:</strong> every 20 minutes</li><li><strong>Location in u19proc2:</strong> /home/u19prod/Datajoint_projs/U19-pipeline_python/u19_pipeline/automatic_job/call_pupillometry_queue_jobs.sh</li><li><strong>Overview:</strong> Calls <a href="https://github.com/BrainCOGS/U19-pipeline-python/blob/master/u19_pipeline/automatic_job/pupillometry_handler.py#L256">check_pupillometry_sessions_queue in the pupillometry handler</a>. Queues a new job on <code>spockvm2</code> for the pupillometry session.</li><li><strong>Log files:</strong> /home/u19prod/log/pupillometry_queue_logs/pqlogs_(datetime execution)</li></ul><h2 id="pupillometry-pipeline-check-process" tabindex="-1">Pupillometry Pipeline Check process <a class="header-anchor" href="#pupillometry-pipeline-check-process" aria-label="Permalink to “Pupillometry Pipeline Check process”">​</a></h2><ul><li><strong>Execution schedule:</strong> daily at 2:00 am</li><li><strong>Location in u19proc2:</strong> /home/u19prod/Datajoint_projs/U19-pipeline_python/u19_pipeline/automatic_job/call_pupillometry_check_jobs.sh</li><li><strong>Overview:</strong> Calls <a href="https://github.com/BrainCOGS/U19-pipeline-python/blob/master/u19_pipeline/automatic_job/pupillometry_handler.py#L338">check_processed_pupillometry_sessions in the pupillometry handler</a>. Checks whether a pupillometry job on <code>spockvm2</code> has finished and retrieves the data to ingest into the <code>pupillometry_session_model_data</code> table.</li><li><strong>Log files:</strong> /home/u19prod/log/pupillometry_check_logs/pclogs_(datetime execution)</li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};